    "modelAnalysis.askAgent": "发给 Agent 分析",
    "modelAnalysis.askAgentHint": "将当前总结发到 AI Chat 并自动发起对话",
    "modelAnalysis.askAgentPromptSingle": "你是机器人学习（ACT / 模仿学习）方向的评测助手。下方是**单个检查点**的产物摘要。\n\n- **run**：{label}\n- **path**：{path}\n\n请基于摘要给出结构化分析（中文），并严格区分「事实」与「推断」：\n\n1. **训练健康度**：train/val loss 是否收敛、是否存在过拟合/欠拟合、best epoch 是否合理\n2. **数据与归一化**：episode 规模、state_dim / max_episode_len、action / qpos / delta 统计是否异常（如 std≈0、极端均值）\n3. **配置审查**：policy_config 中与训练稳定性/容量相关的关键超参（lr、chunk、camera、action_space 等）是否可疑\n4. **可用性判断**：该 ckpt 更适合继续训练、微调还是部署；若不适合，说明主要阻塞点\n5. **下一步建议**：给出 2–3 条可执行建议（实验 / 数据 / 超参），并标注优先级\n\n若摘要缺少关键字段，请列出缺失项，不要编造数值。",
    "modelAnalysis.askAgentPromptCompare": "你是机器人学习（ACT / 模仿学习）方向的评测助手。下方是**多模型对比**摘要。\n\n- **run 数量**：{runs}\n- **基线（对照）**：{baseline}\n- **参与对比**：{labels}\n\n请基于摘要给出结构化对比分析（中文），并严格区分「事实」与「推断」。对比时始终以基线 `{baseline}` 为参照：\n\n1. **总体结论**：哪个 run 综合更优（主要看 val loss / best epoch），一句话说明理由\n2. **训练曲线对比**：各 run 收敛速度、过拟合迹象、best vs final val 差异\n3. **配置差异归因**：policy_config 中实质影响训练的 diff（忽略路径/命名类差异），判断优劣是否可由超参解释\n4. **数据一致性**：dataset_stats 标量/向量是否一致；若不一致，对比是否公平、应如何解读\n5. **差异优先级**：将发现按高/中/低优先级排序，标出可能只是噪声的差异\n6. **实验建议**：若继续 sweep，建议固定哪些变量、优先改哪些变量\n\n若信息不足以公平对比，请明确指出，不要编造数值。",
