    "pi05.route.smoke": "LoRA 冒烟（辅）",
    "pi05.route.smokeHint": "JAX · 双 LoRA · 单卡 32GB 可试",
    "pi05.guide.titleFullFt": "Tl 全参训练提示",
    "pi05.guide.pillFullFt": "Full FT",
    "pi05.guide.pill8gpu": "8×GPU",
    "pi05.guide.pillTl": "Tl",
    "pi05.guide.leadFullFt": "mlu_full_ft* 全参主线：双全参 + torchrun。缺 pi05_base_pytorch 或 GPU<8 时 preflight 会失败。",
    "pi05.guide.row.adapt": "适配",
    "pi05.guide.row.adaptFull": "gemma_2b + gemma_300m 全参",
    "pi05.guide.row.batchFull": "全局 batch=256（≈32/卡）",
    "pi05.guide.row.base": "Base",
    "pi05.guide.row.basePytorch": "checkpoints/pi05_base_pytorch",
    "pi05.guide.row.hw": "硬件",
    "pi05.guide.row.hwFull": "约 8×80GB；非单卡 32GB",
    "pi05.guide.footFullFt": "启动：bash scripts/train_tonglu_full_ft.sh <yaml> · 详见 docs/tonglu_mlu_full_ft_reproduce.md",
    "pi05.theory.title": "训练原理详解",
    "pi05.theory.pill.vla": "VLA",
    "pi05.theory.pill.flow": "Flow matching",
    "pi05.theory.pill.fullFt": "全参",
    "pi05.theory.pill.lora": "LoRA",
    "pi05.theory.leadFullFt": "当前为 Tl 全参主线：在 π0.5 预训练权重上，用多视角观测 + 语言 + 状态条件化 Action Expert，以 flow matching 拟合示教动作分布。下文说明「为什么这样训、每块在学什么」。",
    "pi05.theory.leadSmoke": "当前为 LoRA 冒烟辅线：目标与全参相同（条件化动作生成），但用低秩适配在单卡上验证数据与配置通路；原理结构一致，只是可训练参数子集不同。",
    "pi05.theory.overview.title": "1. 总体：条件生成式模仿学习",
    "pi05.theory.overview.body": "π0.5 不是回归单步关节角的小型 ACT，而是 Vision-Language-Action（VLA）策略：\n· 输入：多相机图像、任务 prompt、本体状态（可离散化）\n· 输出：长度为 action_horizon 的动作 chunk（相对位姿 / 夹爪等）\n· 学习目标：在示教轨迹上，让模型学会「在当前观测条件下，动作应落在哪条流形上」\n预训练 base 已在大规模机器人数据上学会通用操控先验；本步微调把先验对齐到 Tl 任务与相机布局。",
    "pi05.theory.condition.title": "2. 条件编码：观测如何进入网络",
    "pi05.theory.condition.body": "条件侧由 PaliGemma 多模态主干完成：\n· SigLIP：各视角 RGB → 视觉 token（视角数 / 分辨率决定序列长度与显存）\n· Tokenize：任务文本 +（可选）离散状态 → 语言侧 token，受 max_token_len 约束\n· 融合：视觉与语言 token 在共享 Transformer 里交叉注意力，得到「当前情境」表征\ncamera_mapping 把 chest / wrist / top 等业务相机名对齐到模型视觉槽位；映射错了等于用错眼睛训练。",
    "pi05.theory.expert.title": "3. Action Expert：动作块如何生成",
    "pi05.theory.expert.body": "Action Expert（约 Gemma 300M）与 VLM 联合注意力，专责动作序列：\n· 一次预测 action_horizon 步（chunk），部署时可做 temporal aggregation 平滑\n· action_dim 在训练配置中常 pad 到更高维以匹配专家宽度，推理再映射回控制维\n· 全参路线：paligemma_variant=gemma_2b、action_expert_variant=gemma_300m（双全参）\n· LoRA 路线：两侧改 *_lora，只更新低秩适配器，显存显著下降",
    "pi05.theory.flow.title": "4. 损失：Flow matching（不是 MSE 一步回归）",
    "pi05.theory.flow.body": "π0 / π0.5 系用条件 flow matching 学习从噪声到动作的连续流：\n· 在动作空间构造噪声 ↔ 真值动作之间的插值路径\n· 网络预测速度场（或等价目标），使采样能从噪声积到示教动作\n· 条件来自上一节的 VLM 表征，因此「同一观测下」的动作分布被拟合\n这与 ACT 的 CVAE + L1 动作回归不同：flow matching 更适合高维、多峰的动作 chunk，也是预训练权重假设的目标形式——微调应保持同一目标，不要随意改成纯 MSE。",
    "pi05.theory.norm.title": "5. Norm stats：为何必须先算第 2 步",
    "pi05.theory.norm.body": "状态与动作在送入网络前按数据集统计量做归一化（mean/std 等，落在 artifacts/assets）。\n· 无 norm_stats：尺度混乱，flow 目标与预训练先验不对齐，易发散或学不动\n· 换数据集 / 换 action 定义后必须重算，不能复用别的工程的 stats\n· 推理与评测须使用与训练同套 stats，否则动作会整体偏移",
    "pi05.theory.adapt.title": "6. 全参 vs LoRA：在学什么参数",
    "pi05.theory.adapt.body": "全参（Tl 主线）：更新 VLM + Expert 几乎全部权重，表达力最强，需要 ~8×大显存、全局 batch≈256、FSDP。\nLoRA 冒烟：在冻结主干上插低秩矩阵，验证「数据→LeRobot→norm→可反传」链路；配方与全参不同，不能把冒烟 checkpoint 当作 mlu_full_ft* 同级产物。\n改 paligemma_variant / action_expert_variant 会改变参数量与显存，并偏离既定全参配方。",
    "pi05.theory.optim.title": "7. 优化与并行：batch、FSDP、步数",
    "pi05.theory.optim.body": "· 全局 batch：多卡上 per-device batch × 卡数（及梯度累积）凑齐 YAML 中的 batch_size\n· fsdp_devices：分片参数/梯度以塞下全参；须与可见 GPU 数匹配\n· 学习率、warmup、训练步数由 YAML training 段决定；print-only 可先打印 TrainConfig 核对\n· checkpoint 按 exp_name / step 落在 artifacts/checkpoints/…，供后续离线推理与分析页使用",
    "pi05.theory.foot": "配置字段的逐项含义见「环境检测 → 全参 YAML」；显存与开跑清单见上方训练提示。",
    "pi05.step.train.description.full_ft": "选 YAML 文件自动回填超参；点「保存为 YAML」弹出路径写入（与开训无关）。运行时用当前表单生成临时配置（Tl 全参 / torchrun）。",
    "pi05.step.train.description.smoke_lora": "选 YAML 文件自动回填超参；点「保存为 YAML」弹出路径写入（与开训无关）。JAX LoRA 冒烟路径。",
