    "pi05Analysis.node.fallback": "该节点为 π0.5 流水线中的一级模块；结合配置与权重分布可进一步核对容量与适配方式。",
    "pi05Analysis.node.images.body": "多视角 RGB（或 RGB-D）观测。π0.5 通过 camera_mapping 将 chest / wrist / top 等相机对齐到 PaliGemma 的视觉槽位；视角数量与分辨率直接影响 SigLIP 编码长度与显存。",
    "pi05Analysis.node.state.body": "机器人本体状态（常见 7D：xyz + rpy + gripper）。discrete_state_input=true 时会离散化并拼进语言侧 token，使专家网络在同一序列里条件化状态；关闭则走连续投影路径。",
    "pi05Analysis.node.prompt.body": "任务语言指令（task_name / prompt_from_task）。与状态 token 一并进入 tokenize 分支，受 max_token_len 截断；提示词质量会直接影响策略的任务可迁移性。",
    "pi05Analysis.node.siglip.body": "SigLIP 视觉编码器，属于 PaliGemma 视觉塔。将各相机帧编码为视觉 token，再与语言/状态 token 融合。全参微调时视觉塔参数量大，32GB 单卡通常需 LoRA 或冻结策略。",
    "pi05Analysis.node.tokenize.body": "把离散状态与文本 prompt 编成 token 序列，并与视觉 token 对齐时间维。这是 VLM 条件化的入口，决定后续 PaliGemma 看到的上下文组成。",
    "pi05Analysis.node.paligemma.body": "PaliGemma（Gemma 2B 级）多模态主干：融合视觉与语言，产出供 Action Expert 条件化的共享表征。variant 可选 gemma_2b / gemma_2b_lora；width≈2048、depth≈18。权重文件中对应 paligemma_with_expert.paligemma.*。",
    "pi05Analysis.node.expert.body": "Action Expert（Gemma 300M 级）专责动作块生成，与 VLM 联合注意力。可全参或 LoRA；与 time MLP / action proj 配合输出 action_horizon 长度的动作序列。权重前缀 paligemma_with_expert.gemma_expert.*。",
    "pi05Analysis.node.actions.body": "策略输出的动作 chunk（horizon H）。语义通常为相对位姿增量 + 夹爪；action_dim 在训练配置中可能被 pad 到更高维（如 32）以匹配专家宽度，部署时再映射回控制维。",
