    "modelAnalysis.askAgentHint": "Send this summary to AI Chat and start a conversation",
    "modelAnalysis.askAgentPromptSingle": "You are an evaluation assistant for robot learning (ACT / imitation learning). Below is an artifact summary for a **single checkpoint**.\n\n- **run**: {label}\n- **path**: {path}\n\nProvide a structured analysis and clearly separate **facts** from **inferences**:\n\n1. **Training health**: train/val loss convergence, over/under-fitting, whether best epoch looks reasonable\n2. **Data & normalization**: episode count, state_dim / max_episode_len, anomalies in action / qpos / delta stats (e.g. std≈0, extreme means)\n3. **Config review**: suspicious hyperparameters in policy_config that affect stability or capacity (lr, chunk, cameras, action_space, etc.)\n4. **Usability**: whether this ckpt is better suited for continued training, fine-tuning, or deployment; if not, main blockers\n5. **Next steps**: 2–3 actionable recommendations (experiment / data / hyperparams) with priority\n\nIf key fields are missing from the summary, list them — do not invent numbers.",
    "modelAnalysis.askAgentPromptCompare": "You are an evaluation assistant for robot learning (ACT / imitation learning). Below is a **multi-run comparison** summary.\n\n- **runs**: {runs}\n- **baseline**: {baseline}\n- **compared**: {labels}\n\nProvide a structured comparison and clearly separate **facts** from **inferences**. Always use baseline `{baseline}` as the reference:\n\n1. **Overall verdict**: which run is better overall (mainly val loss / best epoch) and why in one sentence\n2. **Curve comparison**: convergence speed, over-fitting signs, best vs final val gaps per run\n3. **Config attribution**: policy_config diffs that materially affect training (ignore path/name-only changes); can performance gaps be explained by hyperparams?\n4. **Data consistency**: whether dataset_stats scalars/vectors match; if not, is the comparison fair and how to interpret it\n5. **Priority ranking**: rank findings high/medium/low; flag likely noise-only diffs\n6. **Experiment advice**: for further sweeps, what to hold fixed and what to change first\n\nIf the summary is insufficient for a fair comparison, say so explicitly — do not invent numbers.",
