    "pi05.guide.row.hwFull": "~8×80GB; not single 32GB",
    "pi05.guide.footFullFt": "Launch: bash scripts/train_tonglu_full_ft.sh <yaml> · see docs/tonglu_mlu_full_ft_reproduce.md",
    "pi05.theory.title": "Training principles",
    "pi05.theory.pill.vla": "VLA",
    "pi05.theory.pill.flow": "Flow matching",
    "pi05.theory.pill.fullFt": "Full FT",
    "pi05.theory.pill.lora": "LoRA",
    "pi05.theory.leadFullFt": "Tl full-FT route: fine-tune π0.5 pretrained weights so a multi-view + language + state–conditioned Action Expert fits the demo action distribution via flow matching. Below: what each block learns and why.",
    "pi05.theory.leadSmoke": "LoRA smoke route: same generative objective as full-FT, but only low-rank adapters update — enough to validate data/config on one GPU. Structure matches; trainable subset differs.",
    "pi05.theory.overview.title": "1. Overall: conditional generative imitation",
    "pi05.theory.overview.body": "π0.5 is a Vision-Language-Action (VLA) policy, not a small ACT that regresses single-step joints:\n· Inputs: multi-camera images, task prompt, proprioception (optionally discretized)\n· Outputs: an action chunk of length action_horizon (relative pose / gripper, …)\n· Objective: under current observations, learn which action manifold demos occupy\nThe pretrained base holds a general manipulation prior; this step aligns it to the Tl task and camera layout.",
    "pi05.theory.condition.title": "2. Conditioning: how observations enter the net",
    "pi05.theory.condition.body": "The condition stack is PaliGemma:\n· SigLIP: each RGB view → vision tokens (view count / resolution drive length & VRAM)\n· Tokenize: task text + optional discrete state → language tokens (max_token_len)\n· Fusion: cross-attention yields a shared “situation” representation\ncamera_mapping maps chest / wrist / top onto model vision slots — a wrong map trains with the wrong eyes.",
    "pi05.theory.expert.title": "3. Action Expert: how action chunks are made",
    "pi05.theory.expert.body": "The Action Expert (~Gemma 300M) attends jointly with the VLM and emits actions:\n· Predicts action_horizon steps at once (chunk); deploy may temporal-aggregate\n· action_dim is often padded to match expert width, then mapped back at control time\n· Full-FT: paligemma_variant=gemma_2b, action_expert_variant=gemma_300m (both full)\n· LoRA: *_lora on both sides — adapters only, much lower VRAM",
    "pi05.theory.flow.title": "4. Loss: flow matching (not one-step MSE)",
    "pi05.theory.flow.body": "π0 / π0.5 learn a conditional flow from noise to actions:\n· Interpolate noise ↔ demo actions in action space\n· The net predicts a velocity field (or equivalent) so sampling integrates noise → demo\n· Conditioning comes from the VLM representation above\nUnlike ACT’s CVAE + L1 regression, flow matching suits high-dim, multimodal chunks and matches the pretrained objective — keep it; do not casually swap to plain MSE.",
    "pi05.theory.norm.title": "5. Norm stats: why step 2 must run first",
    "pi05.theory.norm.body": "State/action are normalized with dataset mean/std (under artifacts/assets) before the net:\n· Without norm_stats, scales fight the pretrained prior → diverge or stall\n· Recompute after dataset / action-def changes; do not reuse another project’s stats\n· Eval/infer must use the same stats as training or actions shift globally",
    "pi05.theory.adapt.title": "6. Full-FT vs LoRA: which weights learn",
    "pi05.theory.adapt.body": "Full-FT (Tl primary): update nearly all VLM + Expert weights — strongest capacity; needs ~8× large GPUs, global batch ≈256, FSDP.\nLoRA smoke: adapters on a frozen trunk to prove data→LeRobot→norm→backward; not equivalent to mlu_full_ft* artifacts.\nChanging paligemma_variant / action_expert_variant changes capacity, VRAM, and leaves the locked full-FT recipe.",
    "pi05.theory.optim.title": "7. Optim & parallel: batch, FSDP, steps",
    "pi05.theory.optim.body": "· Global batch: per-device batch × GPUs (and grad accum) to hit YAML batch_size\n· fsdp_devices: shard params/grads for full-FT; must match visible GPU count\n· LR / warmup / steps live in YAML training; print-only dumps TrainConfig first\n· Checkpoints land under artifacts/checkpoints/… by exp_name / step for infer & analysis",
    "pi05.theory.foot": "Per-key YAML meanings: Setup → Full-FT YAML. VRAM / preflight checklist: the tip panel above.",
    "pi05.step.train.description.full_ft": "Pick a YAML file to auto-fill; Save as YAML opens a path dialog (independent of Run). Run uses a temp config from the form (Tl full FT / torchrun).",
    "pi05.step.train.description.smoke_lora": "Pick a YAML file to auto-fill; Save as YAML opens a path dialog (independent of Run). JAX LoRA smoke path.",
