    "pi05Analysis.node.images.body": "Multi-view RGB (or RGB-D) observations. camera_mapping aligns chest / wrist / top cameras to PaliGemma vision slots; view count and resolution drive SigLIP sequence length and VRAM.",
    "pi05Analysis.node.state.body": "Proprioceptive state (often 7D: xyz + rpy + gripper). With discrete_state_input=true, state is discretized into language-side tokens so the expert is conditioned in-sequence; otherwise a continuous projection path is used.",
    "pi05Analysis.node.prompt.body": "Task language (task_name / prompt_from_task). Joins state tokens in the tokenize branch and is clipped by max_token_len; prompt quality strongly affects task transfer.",
    "pi05Analysis.node.siglip.body": "SigLIP vision encoder inside PaliGemma’s vision tower. Encodes each camera frame into visual tokens fused with language/state. Full FT of the tower is heavy; 32GB cards usually need LoRA or freezing.",
    "pi05Analysis.node.tokenize.body": "Packs discrete state and text prompt into tokens aligned with visual tokens. This is the VLM conditioning entry and defines the context PaliGemma sees.",
    "pi05Analysis.node.paligemma.body": "PaliGemma (~Gemma 2B) multimodal backbone fusing vision and language for the Action Expert. Variants: gemma_2b / gemma_2b_lora (width≈2048, depth≈18). Weights live under paligemma_with_expert.paligemma.*.",
    "pi05Analysis.node.expert.body": "Action Expert (~Gemma 300M) generates action chunks with joint attention to the VLM. Full FT or LoRA; works with time MLP / action proj for action_horizon outputs. Prefix: paligemma_with_expert.gemma_expert.*.",
    "pi05Analysis.node.actions.body": "Predicted action chunk of horizon H. Semantics are usually relative pose deltas + gripper; action_dim may be padded (e.g. to 32) for the expert width and mapped back at deploy time.",
